import assert from 'node:assert/strict';import {resolve} from 'node:path';import {mkdir,writeFile} from 'node:fs/promises';
import {build,preview} from './lib/vite-conferencia.mjs';import react from '@vitejs/plugin-react';import tailwindcss from '@tailwindcss/vite';import {chromium} from 'playwright';
import {criarCenarioSubsistemas} from '../supabase/tests/subsistemas-fixture.mjs';import {especialidades} from '../src/lib/especialidades.ts';
process.env.DB_VALIDATION_RUNTIME=resolve('node_modules/@electric-sql/pglite/dist/index.js');process.env.DB_VALIDATION_MIGRATION_LIMIT='99999999999999';
const pasta=resolve('output/gestao-operacao-velocidade-20261118/site-completo');await mkdir(pasta,{recursive:true});
const {db,login,ids,registros}=await criarCenarioSubsistemas();const contextos=Object.fromEntries(Object.entries(registros).map(([perfil,r])=>[perfil,{usuario:ids[perfil],oficina:{id:r.w,nome:'QA '+perfil,perfil:'owner',ramo:especialidades[perfil].ramo,especialidade:perfil}}]));
let fila=Promise.resolve();const serial=fn=>{const r=fila.then(fn);fila=r.catch(()=>{});return r};
const call=async(nome,args)=>Object.values((await db.query(`select public.${nome}(${args.map((_,i)=>'$'+(i+1)).join(',')})`,args)).rows[0])[0];
const errosRpc=[],resultados=[],falhas=[];
const portalVazio=portal=>{assert(Array.isArray(portal.clientes));for(const valor of Object.values(portal))assert.deepEqual(valor,[])};
const api={name:'api-site-isolada',configurePreviewServer(server){server.middlewares.use((req,res,next)=>{const url=new URL(req.url,'http://localhost');if(url.pathname==='/test-context'){res.setHeader('Content-Type','application/json');res.end(JSON.stringify(contextos[url.searchParams.get('perfil')]));return}if(!url.pathname.startsWith('/rest/v1/rpc/'))return next();let body='';req.on('data',b=>body+=b);req.on('end',()=>void serial(async()=>{const nome=url.pathname.split('/').at(-1);try{assert.match(nome,/^[a-z_]+$/);const args=JSON.parse(body),perfil=Object.keys(registros).find(k=>registros[k].w===args.p_oficina);assert(perfil,'Empresa fora da bancada');await login(ids[perfil]);const keys=Object.keys(args);assert(keys.every(k=>/^p_[a-z_]+$/.test(k)));const r=Object.values((await db.query(`select public.${nome}(${keys.map((k,i)=>k+' => $'+(i+1)).join(',')})`,keys.map(k=>args[k]&&typeof args[k]==='object'?JSON.stringify(args[k]):args[k]))).rows[0])[0];res.setHeader('Content-Type','application/json');res.end(JSON.stringify(r))}catch(e){errosRpc.push({nome,erro:e.message});res.statusCode=400;res.setHeader('Content-Type','application/json');res.end(JSON.stringify({message:e.message,code:e.code||'QA'}))}}))})}};
const config={configFile:false,envDir:false,plugins:[react(),tailwindcss(),api],logLevel:'error',define:{'import.meta.env.VITE_SUPABASE_URL':'window.location.origin','import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY':JSON.stringify('qa-local')},build:{target:'esnext',outDir:resolve(pasta,'build'),rollupOptions:{input:'scripts/fixtures/site-gestao-auditoria.html'}}};
let server,browser,p;
try{await build(config);server=await preview({...config,preview:{host:'127.0.0.1',port:0}});const base=server.resolvedUrls.local[0];browser=await chromium.launch({headless:true,executablePath:'C:/Program Files/Google/Chrome/Application/chrome.exe'});
for(const [perfil,r]of Object.entries(registros)){await serial(async()=>{await login(ids[perfil]);await call('definir_acesso_portal',[r.w,r.cliente,'customer@subsistemas.test',true])});const ctx=await browser.newContext({viewport:{width:390,height:844},locale:'pt-BR'});p=await ctx.newPage();p.setDefaultTimeout(20000);const erros=[];p.on('pageerror',e=>erros.push(e.message));await ctx.route('**/*',route=>new URL(route.request().url()).origin===new URL(base).origin?route.continue():route.abort());
const etapas=[];const medir=async(nome,fn)=>{const t=performance.now();await fn();etapas.push({nome,segundos:(performance.now()-t)/1000})};
await p.goto(base+'scripts/fixtures/site-gestao-auditoria.html?perfil='+perfil);await p.getByText('Apresentação',{exact:true}).click();
await medir('Personalizar e salvar site',async()=>{await p.getByLabel('Endereço do site',{exact:true}).fill('qa-gestao-'+perfil.replaceAll('_','-'));await p.getByLabel('Título',{exact:true}).fill('Site QA '+perfil);await p.getByLabel('Publicar site',{exact:true}).check();await p.getByLabel('Habilitar área do cliente',{exact:true}).check();await p.getByRole('button',{name:'Salvar site',exact:true}).click();await p.getByRole('status').filter({hasText:'Alteração salva.'}).waitFor()});
await medir('Publicar produto',async()=>{await p.getByText('Produtos exibidos no site',{exact:true}).click();await p.getByRole('button',{name:'Publicar produto',exact:true}).first().click();await p.getByRole('button',{name:'Ocultar do site',exact:true}).first().waitFor()});
await medir('Liberar acesso ao cliente',async()=>{await p.getByText('Acesso dos clientes',{exact:true}).click();await p.locator('label').filter({hasText:/^Cliente/}).getByRole('combobox').selectOption({index:1});await p.getByLabel('E-mail confirmado',{exact:true}).fill('customer@subsistemas.test');await p.getByRole('button',{name:'Liberar acesso ao cliente selecionado',exact:true}).click();await p.getByRole('button',{name:'Revogar acesso',exact:true}).waitFor();await p.getByRole('button',{name:'Liberar acesso ao cliente selecionado',exact:true}).waitFor();await p.waitForFunction(()=>[...document.querySelectorAll('button')].some(b=>b.textContent==='Liberar acesso ao cliente selecionado'&&!b.disabled))});
await serial(async()=>{await login('', 'anon');const site=await call('consultar_site_publicado',['qa-gestao-'+perfil.replaceAll('_','-')]);assert(site);assert(site.produtos.length>0);await login(ids.customer);const portal=await call('consultar_meu_portal',[r.w]);assert(portal.clientes.length>0);await login(ids.stranger);portalVazio(await call('consultar_meu_portal',[r.w]))});
for(const width of [390,1920]){await p.setViewportSize({width,height:width===390?844:1080});assert(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+2),'Largura do site '+perfil);if(['retifica','assistencia_celulares','manutencao_climatizacao','limpeza_geral'].includes(perfil))await p.screenshot({path:resolve(pasta,perfil+'-'+width+'.png'),fullPage:true})}
await medir('Revogar acesso e conferir',async()=>{await p.getByRole('button',{name:'Revogar acesso',exact:true}).click();await p.getByRole('button',{name:'Revogar acesso',exact:true}).waitFor({state:'hidden'});await serial(async()=>{await login(ids.customer);portalVazio(await call('consultar_meu_portal',[r.w]))})});
await p.reload();await p.getByText('Apresentação',{exact:true}).click();assert.equal(await p.getByLabel('Título',{exact:true}).inputValue(),'Site QA '+perfil);assert.deepEqual(erros,[]);resultados.push({perfil,etapas,layout:[390,1920],persistencia:true,isolamento:true,revogacao:true});await ctx.close();console.log('PASS site',perfil);
await writeFile(resolve(pasta,'resultados.json'),JSON.stringify({ok:true,ambiente:'Navegador real e PostgreSQL local descartável; nenhum site real publicado, nenhuma mensagem enviada',resultados,errosRpc,falhas},null,2));
}}catch(e){falhas.push(e.message);await p?.screenshot({path:resolve(pasta,'falha.png'),fullPage:true}).catch(()=>{});if(p)await writeFile(resolve(pasta,'falha.txt'),await p.locator('body').innerText().catch(()=>''));console.error(e.stack);process.exitCode=1}
finally{await browser?.close();if(server){server.httpServer.closeAllConnections();await new Promise(r=>server.httpServer.close(r))}await db.close();await writeFile(resolve(pasta,'resultados.json'),JSON.stringify({ok:falhas.length===0&&errosRpc.length===0,ambiente:'Navegador real e PostgreSQL local descartável; nenhum site real publicado, nenhuma mensagem enviada',resultados,errosRpc,falhas},null,2))}
